const incompleteDeps=t=>t.deps.filter(id=>taskState(id).status!=='done');
const dateValid=v=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;const d=new Date(v+'T12:00:00');return !isNaN(d)&&d.getFullYear()===+v.slice(0,4)&&d.getMonth()+1===+v.slice(5,7)&&d.getDate()===+v.slice(8,10);};
function dayDate(day,full=false){if(!dateValid(state.settings.startDate))return `D${day}`;const date=new Date(state.settings.startDate+'T12:00:00');date.setDate(date.getDate()+day-1);return date.toLocaleDateString('vi-VN',full?{day:'2-digit',month:'2-digit',year:'numeric'}:{day:'2-digit',month:'2-digit'});}
function toast(msg,error=false){clearTimeout(toastTimer);$('toast').textContent=msg;$('toast').className='toast visible'+(error?' error':'');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4500);}
function persist(){state.updatedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;$('saveStatus').textContent='Đã lưu trên trình duyệt';}catch{storageOK=false;$('saveStatus').textContent='Lưu trong phiên · hãy xuất JSON';}$('footerState').textContent='Cập nhật '+new Date(state.updatedAt).toLocaleString('vi-VN')+' · Trạng thái do nhóm nhập.';}
function validateState(raw){if(!raw||raw.projectId!==PROJECT||raw.schemaVersion!==1)throw Error('JSON không đúng dự án hoặc phiên bản định dạng.');const s=emptyState();s.auditRevision=raw.auditRevision||5;s.precisionRevision=raw.precisionRevision===1?1:0;s.updatedAt=typeof raw.updatedAt==='string'?raw.updatedAt.slice(0,80):null;const st=raw.settings||{};for(const k of ['startDate','sourceDtype','runRef','projectNote'])if(typeof st[k]==='string')s.settings[k]=st[k].slice(0,k==='projectNote'?5000:500);if(s.settings.startDate&&!dateValid(s.settings.startDate))throw Error('Ngày bắt đầu không hợp lệ.');if(!['unknown','fp32','fp16','mixed'].includes(s.settings.sourceDtype))throw Error('Dtype nguồn không hợp lệ.');for(const k of ['thresholdsConfirmed','protocolConfirmed'])s.settings[k]=st[k]===true;
 for(const t of DATA.tasks){const r=raw.tasks?.[t.id];if(!r)continue;if(!Object.hasOwn(STATUS,r.status))throw Error('Trạng thái không hợp lệ ở '+t.id);s.tasks[t.id]={status:r.status,evidence:String(r.evidence||'').slice(0,4000),note:String(r.note||'').slice(0,5000)};if(r.status==='done'&&!s.tasks[t.id].evidence.trim())throw Error(t.id+' hoàn thành nhưng thiếu bằng chứng.');}
 for(const t of DATA.tasks)if(s.tasks[t.id]?.status==='done'&&t.deps.some(id=>s.tasks[id]?.status!=='done'))throw Error(t.id+' hoàn thành nhưng còn phụ thuộc chưa xong.');
 for(const d of DATA.deliverables){const r=raw.deliverables?.[d.id];if(!r)continue;s.deliverables[d.id]={done:r.done===true,evidence:String(r.evidence||'').slice(0,4000),note:String(r.note||'').slice(0,5000)};if(s.deliverables[d.id].done&&!s.deliverables[d.id].evidence.trim())throw Error(d.id+' thiếu bằng chứng.');}
 const readNum=(v,type)=>{if(v===null||v===undefined||v==='')return null;if(typeof v!=='number'||!Number.isFinite(v))throw Error('Số đo không hợp lệ.');if(type==='percent'&&(v<0||v>100))throw Error('mAP phải trong khoảng 0–100.');if(type==='positive'&&v<=0)throw Error('Dung lượng và thời gian phải lớn hơn 0.');if(type==='drop'&&(v< -100||v>100))throw Error('Delta AP ngoài khoảng hợp lệ.');return v;};
 for(const k of ['sourceSize','dev50','dev95','maxClassDrop'])s.metrics[k]=readNum(raw.metrics?.[k],k==='sourceSize'?'positive':k==='maxClassDrop'?'drop':'percent');
 for(const m of ['b0','f16','q8']){for(const k of FIELDS)s.metrics[m][k]=readNum(raw.metrics?.[m]?.[k],k.startsWith('map')?'percent':'positive');}
 for(const k of Object.keys(EVIDENCE))s.evidence[k]=String(raw.evidence?.[k]||'').slice(0,4000);return s;}
