function migrateLegacyState(raw){
 if(raw.auditRevision===5)return raw;
 const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
 for(const [section,key,before,after] of LEGACY_CORRECTIONS){
  const parent=section?raw[section]:raw;
  if(!parent)continue;
  if(!section&&['tasks','deliverables'].includes(key)){
   for(const id of Object.keys(before)){
    if(same(parent[key]?.[id],before[id]))parent[key][id]=JSON.parse(JSON.stringify(after[id]));
   }
  }else if(same(parent[key],before))parent[key]=JSON.parse(JSON.stringify(after));
 }
 // Preserve user evidence; a completed task with an unverified prerequisite needs review.
 for(let pass=0;pass<DATA.tasks.length;pass++){
  for(const task of DATA.tasks){
   const saved=raw.tasks?.[task.id];
   if(saved?.status==='done'&&task.deps.some(id=>raw.tasks?.[id]?.status!=='done')){
    saved.status='review';saved.note=(saved.note||'')+' Cần kiểm tra lại phụ thuộc sau kiểm toán.';
   }
  }
 }
 // The shipped checkpoint stores FP16: its bytes are not a standardized FP32 reference.
 if(raw.settings?.runRef==='evaluation_int8_yolo26m_640/report.json'&&raw.metrics?.sourceSize===42.02248477935791){
  if(raw.metrics.b0?.size===42.02248477935791)raw.metrics.b0.size=null;
  if(raw.settings.sourceDtype==='unknown')raw.settings.sourceDtype='fp16';
  raw.metrics.sourceSize=null;
 }
 raw.auditRevision=5;return raw;
}
function migratePrecisionState(raw){
 if(raw.precisionRevision===1)return raw;
 if(raw.metrics){
  raw.metrics.b0=Object.fromEntries(FIELDS.map(f=>[f,null]));
  raw.metrics.dev50=null;raw.metrics.dev95=null;raw.metrics.maxClassDrop=null;
  for(const key of ['f16','q8'])if(raw.metrics[key])for(const f of ['p50','p95'])raw.metrics[key][f]=null;
 }
 if(raw.settings){raw.settings.protocolConfirmed=false;raw.settings.thresholdsConfirmed=false;
  if(raw.settings.projectNote===VERIFIED_STATE.settings.projectNote)raw.settings.projectNote='Baseline hiện chạy PyTorch CPU FP16; trọng số và input float16. Số đo baseline cũ không dùng làm kết quả FP16; chờ đánh giá lại accuracy. Các ngưỡng nghiệm thu giữ nguyên, cần xác nhận lại protocol.';
 }
 raw.precisionRevision=1;return raw;
}
try{
 const saved=localStorage.getItem(KEY);
 if(saved){
  const raw=JSON.parse(saved);
  if(raw.auditRevision!==5&&!localStorage.getItem(KEY+':before-audit-v5'))localStorage.setItem(KEY+':before-audit-v5',saved);
  if(raw.precisionRevision!==1&&!localStorage.getItem(KEY+':before-fp16'))localStorage.setItem(KEY+':before-fp16',saved);
  state=validateState(migratePrecisionState(migrateLegacyState(raw)));
  persist();$('saveStatus').textContent='Đã khôi phục trên trình duyệt';
 }else{state=completedProjectState();persist();$('saveStatus').textContent='Đã tải dữ liệu đã đối chiếu · chưa nghiệm thu';}
}catch(e){state=completedProjectState();storageOK=false;$('saveStatus').textContent='Không đọc được bản lưu · bản gốc vẫn được giữ';}

function statusBadge(s,interactive=false,id=''){return interactive?`<button class="status-btn ${s}" data-task="${id}" aria-label="Cập nhật ${id}: ${STATUS[s]}"><span class="badge-dot"></span>${STATUS[s]}</button><span class="print-only">${STATUS[s]}</span>`:`<span class="pill ${s==='done'?'ok':s==='progress'?'accent':s==='review'?'warn':''}">${STATUS[s]}</span>`;}
function renderProgress(){const required=DATA.tasks.filter(t=>t.scope==='required'),done=required.filter(t=>taskState(t.id).status==='done').length,p=Math.round(done/required.length*100);$('progressValue').innerHTML=`${p}<small>%</small>`;$('progressFoot').textContent=`${done} / ${required.length} nhiệm vụ hoàn thành`;$('sideCount').textContent=`${done} / ${required.length} nhiệm vụ bắt buộc`;$('sideBar').style.width=p+'%';const active=DATA.tasks.some(t=>taskState(t.id).status!=='todo');$('sideStage').textContent=done===required.length?'Hoàn tất các nhiệm vụ bắt buộc':active?'Đang cập nhật theo tiến độ nhóm':'Kế hoạch dự kiến · chưa bắt đầu';}
function renderTimeline(){const selected=DATA.days[selectedDay-1];$('dateRange').textContent=state.settings.startDate?`${dayDate(1,true)} → ${dayDate(14,true)}`:'Chưa xác nhận';$('dayGrid').innerHTML=DATA.days.map(d=>{const required=d.tasks.map(taskById).filter(t=>t.scope==='required');const allDone=required.length&&required.every(t=>taskState(t.id).status==='done');return `<button class="day-btn ${d.day===selectedDay?'selected':''} ${[8,13].includes(d.day)?'buffer':''} ${allDone?'complete':''}" data-day="${d.day}" aria-pressed="${d.day===selectedDay}" title="${esc(d.title)}"><small>NGÀY</small><span class="day-number">${String(d.day).padStart(2,'0')}</span><small>${state.settings.startDate?dayDate(d.day):[8,13].includes(d.day)?'Dự phòng':'Kế hoạch'}</small><i class="day-dot"></i></button>`;}).join('');$('dayDetail').innerHTML=`<div><div class="eyebrow">NGÀY ${selectedDay} ${state.settings.startDate?'· '+dayDate(selectedDay,true):''}</div><h3>${selected.title}</h3><p class="muted">${selected.goal}</p><p><strong>Đầu ra trong ngày</strong><br><span class="muted">${selected.output}</span></p>${selected.gate?`<span class="pill accent">${selected.gate}</span>`:''}${[8,13].includes(selectedDay)?'<p class="small muted" style="margin-top:10px">Quỹ đệm để sửa lỗi, không mở thêm kỹ thuật nén.</p>':''}</div><div>${selected.tasks.map(id=>{const t=taskById(id);return `<div class="day-task"><div><div class="day-task-title"><span class="mono muted">${id}</span> ${t.title}</div><small class="muted">TV${t.owner} phụ trách · TV${t.reviewer} kiểm tra · Phụ thuộc: ${t.deps.join(', ')||'Có thể khởi động'}</small><div>${statusBadge(taskState(id).status)}</div></div><button class="btn tiny" data-task="${id}">Chi tiết</button></div>`;}).join('')}</div>`;
 $('gateStrip').innerHTML=DATA.days.filter(d=>d.gate).map(d=>{let ts=d.gateTasks.map(taskById);let done=ts.every(t=>taskState(t.id).status==='done');return `<div class="gate-card"><span class="muted">D${d.day} · ${d.gateTasks.join(" / ")}</span><strong>${d.gate.split(' · ')[1]}</strong><span class="pill ${done?'ok':''}">${done?'Đã đủ tác vụ':'Chờ bằng chứng'}</span></div>`;}).join('');
 $('printCalendar').innerHTML=`<table class="print-calendar"><thead><tr><th>Ngày</th><th>Mục tiêu & mốc</th><th>Công việc / phụ trách → kiểm tra</th><th>Đầu ra</th></tr></thead><tbody>${DATA.days.map(d=>`<tr><td>D${d.day}<br>${state.settings.startDate?dayDate(d.day):''}</td><td><strong>${d.title}</strong><br>${d.goal}<br>${d.gate}</td><td>${d.tasks.map(id=>{let t=taskById(id);return `${id}: ${t.title} · TV${t.owner} → TV${t.reviewer}`;}).join('<br>')}</td><td>${d.output}</td></tr>`).join('')}</tbody></table>`;}
function getFilteredTasks(){const search=$('taskSearch').value.trim().toLocaleLowerCase('vi'),owner=$('ownerFilter').value,status=$('statusFilter').value,priority=$('priorityFilter').value,scope=$('scopeFilter').value,ready=$('readyOnly').checked;return DATA.tasks.filter(t=>(!search||`${t.id} ${t.title} ${t.output}`.toLocaleLowerCase('vi').includes(search))&&(!owner||t.owner===+owner)&&(!status||taskState(t.id).status===status)&&(!priority||t.priority===priority)&&(!scope||t.scope===scope)&&(!ready||(taskState(t.id).status!=='done'&&!incompleteDeps(t).length)));}
function renderTasks(all=false){const items=all?DATA.tasks:getFilteredTasks();$('taskRows').innerHTML=items.length?items.map(t=>{const s=taskState(t.id),deps=incompleteDeps(t);return `<tr><td><span class="task-id mono">${t.id}</span><br><span class="task-sub">${SCOPES[t.scope]}</span></td><td><span class="task-title">${t.title}</span><span class="task-sub">${t.output}</span><span class="task-sub">Kiểm tra: TV${t.reviewer} · Phụ thuộc: ${t.deps.join(', ')||'Không'}</span>${deps.length?`<span class="dependency-warning">Chờ: ${deps.join(', ')}</span>`:''}<div class="print-only print-task-details"><b>Đầu vào:</b> ${t.input}<br><b>Hoàn thành khi:</b> ${t.done}<br><b>Dự phòng:</b> ${t.fallback}${s.evidence?'<br><b>Bằng chứng:</b> '+esc(s.evidence):''}${s.note?'<br><b>Ghi chú:</b> '+esc(s.note):''}</div></td><td><span class="person"><span class="avatar">${t.owner}</span>TV${t.owner}</span></td><td><span class="small">${dayDate(t.start)} → ${dayDate(t.end)}</span></td><td><span class="priority ${t.priority}">${t.priority}</span></td><td>${statusBadge(s.status,true,t.id)}</td><td><button class="btn tiny" data-task="${t.id}" aria-label="Chi tiết ${t.id}">Mở</button></td></tr>`;}).join(''):'<tr><td colspan="7"><div class="no-results">Không có nhiệm vụ khớp bộ lọc. Thử xóa bộ lọc hoặc từ khóa.</div></td></tr>';$('filterCount').textContent=`Hiển thị ${items.length} / ${DATA.tasks.length} nhiệm vụ`;
}
function renderTeam(){ $('memberCards').innerHTML=DATA.members.map(m=>{const ts=DATA.tasks.filter(t=>t.owner===m.id&&t.scope==='required'),done=ts.filter(t=>taskState(t.id).status==='done').length;return `<div class="panel member-card"><span class="avatar">${m.id}</span><h3>Thành viên ${m.id}</h3><p>${m.role}</p><div class="member-progress"><i style="width:${done/ts.length*100}%"></i></div><small>${done}/${ts.length} việc bắt buộc hoàn thành</small></div>`;}).join('');
 $('memberDetails').innerHTML=DATA.members.map(m=>`<details><summary><span>Thành viên ${m.id} · ${m.role}</span><span class="pill">${m.deadline}</span></summary><div class="detail-body"><div class="detail-grid"><p><strong>Trách nhiệm chính</strong>${m.focus}<br>${DATA.tasks.filter(t=>t.owner===m.id).map(t=>t.id).join(' · ')}</p><p><strong>Nhiệm vụ phối hợp</strong>${m.coord}</p><p><strong>Đầu ra & tiêu chí hoàn thành</strong>${m.output}<br>${m.criterion}</p><p><strong>Phụ thuộc & kiểm tra chéo</strong>${m.depends}<br>${m.review}</p></div></div></details>`).join(''); }
function renderStatic(){ $('protocolCards').innerHTML=DATA.protocol.map(p=>`<article class="panel protocol-card"><div class="step-n">BƯỚC ${p.n}</div><h3>${p.title}</h3><dl><dt>Đầu vào</dt><dd>${p.input}</dd><dt>Thực hiện</dt><dd>${p.action}</dd><dt>Đầu ra</dt><dd>${p.output}</dd><dt>Điều kiện chuyển bước</dt><dd>${p.gate}</dd></dl></article>`).join('');$('riskRows').innerHTML=DATA.risks.map(r=>`<tr><td><span class="mono muted">${r.id}</span><br><strong>${r.name}</strong></td><td>${r.prob}</td><td>${r.impact}</td><td>${r.signal}</td><td>${r.prevention}</td><td>${r.fallback}</td><td>TV${r.owner}</td></tr>`).join('');
 $('modelMetrics').innerHTML=Object.keys(MODEL_NAMES).map(m=>`<tr><td><strong>${MODEL_NAMES[m]}</strong><span class="task-sub">${m==='q8'?'OpenVINO INT8 · CPU':m==='b0'?'PyTorch FP16 · CPU':'Chưa xác minh FP16 YOLO26m'}</span></td>${FIELDS.map(f=>`<td><label class="screen-reader" for="${m}_${f}">${MODEL_NAMES[m]} ${f}</label><input id="${m}_${f}" type="number" min="${f.startsWith('map')?'0':'0.000001'}" ${f.startsWith('map')?'max="100"':''} step="any" data-model="${m}" data-field="${f}" placeholder="Chưa đo"><span class="print-value" data-print-for="${m}_${f}">Chưa đo</span></td>`).join('')}</tr>`).join('');
 $('evidenceFields').innerHTML=Object.entries(EVIDENCE).map(([k,v])=>`<label class="field">${v}<input id="evidence_${k}" data-evidence="${k}" placeholder="Tệp / log / commit và người kiểm tra"><span class="print-value" data-print-for="evidence_${k}">Chưa ghi</span></label>`).join('');}
function renderDeliverables(){const mandatory=DATA.deliverables.filter(d=>!d.optional);$('deliveryCount').textContent=`${mandatory.filter(d=>deliveryState(d.id).done).length} / ${mandatory.length} đầu ra bắt buộc`;$('deliveryCards').innerHTML=DATA.deliverables.map(d=>{const s=deliveryState(d.id);return `<article class="panel deliverable ${s.done?'done':''}"><button class="check" data-delivery="${d.id}" aria-label="${s.done?'Cập nhật':'Đánh dấu'} ${esc(d.title)}" aria-pressed="${s.done}">${s.done?icon('check'):''}</button><div><h3>${d.title}${d.optional?' <span class="pill">Tùy chọn</span>':''}</h3><p>${d.desc}</p><div class="delivery-meta">${d.id} · TV${d.owner} · Hạn ${dayDate(d.day)} · ${s.done?'Hoàn thành theo xác nhận nhóm':'Chưa hoàn thành'}</div>${s.evidence?`<div class="evidence">Bằng chứng: ${esc(s.evidence)}</div>`:''}<button class="edit-link" data-delivery="${d.id}">Cập nhật bằng chứng</button></div></article>`;}).join('');}
function numericErrors(){const errors=[];if(document.querySelector('input[aria-invalid="true"]'))errors.push('Có ô nhập số không hợp lệ; hãy sửa hoặc xóa ô được đánh dấu.');for(const m of Object.keys(MODEL_NAMES)){const v=state.metrics[m];if(v.map50!=null&&v.map95!=null&&v.map95>v.map50)errors.push(MODEL_NAMES[m]+': mAP@50–95 không được lớn hơn mAP@50.');if(v.p50!=null&&v.p95!=null&&v.p95<v.p50)errors.push(MODEL_NAMES[m]+': p95 không được nhỏ hơn p50.');}if(state.metrics.dev50!=null&&state.metrics.dev95!=null&&state.metrics.dev95>state.metrics.dev50)errors.push('Baseline development: mAP@50–95 không được lớn hơn mAP@50.');return errors;}
function reduction(a,b){return a!=null&&b!=null&&a>0&&b>0?(1-b/a)*100:null;}
function delta(a,b){return a!=null&&b!=null?a-b:null;}
function criteria(){const m=state.metrics,b=m.b0,q=m.q8;return [
 {name:'Giảm so với checkpoint FP16',base:b.size,after:q.size,unit:'MiB',change:reduction(b.size,q.size),changeUnit:'%',threshold:'≥60%',pass:v=>v>=60,desc:'Checkpoint và suy luận baseline dùng FP16. Ngưỡng 60% giữ nguyên; cần số đo mới theo protocol FP16.'},
 {name:'Giảm so với gói nguồn sạch',base:m.sourceSize,after:q.size,unit:'MiB',change:reduction(m.sourceSize,q.size),changeUnit:'%',threshold:'≥40%',pass:v=>v>=40,desc:'Cần gói nguồn sạch chuẩn hóa; checkpoint gốc chưa được dùng thay mốc này.'},
 {name:'mAP@50',base:b.map50,after:q.map50,unit:'',change:delta(b.map50,q.map50),changeUnit:'điểm',threshold:'Δ ≤2 điểm',pass:v=>v<=2,desc:'Δ = B0 − Q8. Âm nghĩa là điểm đo Q8 cao hơn.'},
 {name:'mAP@50–95',base:b.map95,after:q.map95,unit:'',change:delta(b.map95,q.map95),changeUnit:'điểm',threshold:'Δ ≤2 điểm',pass:v=>v<=2,desc:'Số đo hiện có dùng cùng validation manifest; chưa xác minh held-out final.'}
 ];}
function renderEvaluation(){const rows=criteria(),errors=numericErrors();$('metricError').textContent=errors.join(' ');$('criteriaRows').innerHTML=rows.map(r=>`<tr><td><strong>${r.name}</strong></td><td class="value">${num(r.base)}${r.base!=null?' '+r.unit:''}</td><td class="value">${num(r.after)}${r.after!=null?' '+r.unit:''}</td><td class="value">${num(r.change)}${r.change!=null?' '+r.changeUnit:''}</td><td>${r.threshold}</td><td><span class="pill ${r.change==null?'':r.pass(r.change)?'ok':'bad'}">${r.change==null?'Chưa đo':r.pass(r.change)?'Đạt ngưỡng':'Chưa đạt'}</span></td><td>${r.desc}</td></tr>`).join('');
 const d=state.metrics,known=rows.filter(r=>r.change!=null),fail=known.some(r=>!r.pass(r.change)),classFail=d.maxClassDrop!=null&&d.maxClassDrop>5,baseKnown=d.dev50!=null&&d.dev95!=null,baseGood=baseKnown&&d.dev50>=45&&d.dev95>=25,all=known.length===4;let title='Chưa có kết quả thực nghiệm',description='Nhập số đo B0 và Q8 để đối chiếu các tiêu chí định lượng.',kind='';
 const evidenceGood=Object.keys(EVIDENCE).every(k=>(state.evidence[k]||'').trim()),metaGood=state.settings.thresholdsConfirmed&&state.settings.protocolConfirmed&&state.settings.runRef.trim()&&state.settings.sourceDtype!=='unknown';
 if(errors.length){title='Cần sửa dữ liệu không nhất quán';description='Chưa đưa ra kết luận từ số liệu không hợp lệ. '+errors.join(' ');kind='bad';}
 else if(fail||classFail){title=classFail?'Cần điều tra suy giảm theo lớp':'Q8 chưa đạt ngưỡng định lượng';description=classFail?'Một lớp đủ mẫu giảm AP trên 5 điểm. mAP tổng đạt cũng chưa đủ xác nhận chất lượng.':'Dung lượng và chất lượng phải đồng thời đạt. Giữ kết quả này, không điều chỉnh bằng cách dùng tập final.';kind='bad';}
 else if(all){if(!baseGood||d.maxClassDrop==null||!evidenceGood||!metaGood){title='Đạt các ngưỡng chính · chờ kiểm chứng';description='Còn cần baseline development, kiểm tra AP theo lớp, xác nhận protocol/ngưỡng và đủ bằng chứng trước khi kết luận.';kind='pending';}else{title='Đủ tiêu chí theo dữ liệu nhóm nhập';description='Q8 đạt các ngưỡng đã chọn và nhóm đã ghi bằng chứng. Người kiểm tra vẫn chịu trách nhiệm đối chiếu các tệp/log; dashboard không tự xác minh thí nghiệm.';kind='good';}}
 else if(known.length){title='Đang có số đo · chưa đủ kết luận';description='Cần đủ hai mốc dung lượng và cả hai mAP của B0/Q8. Ô trống không được coi là 0.';kind='pending';}
 $('resultBox').className='result-box '+kind;$('resultBox').innerHTML=`<h3>${title}</h3><p>${description}</p>`;
 $('metricKpi').textContent=errors.length?'Kiểm tra số liệu':fail||classFail?'Chưa đạt':all?'Đã có số đo':known.length?'Đang nhập':'Chưa đo';$('metricKpiFoot').textContent=all?'Xem kết luận & bằng chứng bên dưới':known.length?'Còn thiếu mốc hoặc bằng chứng':'Chưa có số đo';
 $('baselineGate').textContent=baseKnown?(baseGood?'Baseline đạt mốc sàng lọc đề xuất.':'Baseline dưới mốc đề xuất: kiểm tra pipeline/checkpoint trước khi diễn giải giữ chất lượng.'):'Mốc sàng lọc đề xuất: ≥45 / ≥25; không phải chuẩn chính thức BDD100K.';
 $('thresholdStatus').textContent=state.settings.thresholdsConfirmed?'Ngưỡng đã được nhóm xác nhận':'Ngưỡng đề xuất · cần xác nhận';$('thresholdStatus').className='pill '+(state.settings.thresholdsConfirmed?'accent':'warn');renderPlot();syncPrintValues();}
function renderPlot(){const points=Object.keys(MODEL_NAMES).filter(k=>state.metrics[k].size!=null&&state.metrics[k].map95!=null).map(k=>({k,size:state.metrics[k].size,ap:state.metrics[k].map95}));if(!points.length){$('tradeoffPlot').innerHTML=`<div class="empty-state"><div class="empty-icon">${icon('chart')}</div><strong>Chưa có điểm thực nghiệm</strong>Nhập dung lượng và mAP@50–95 để hiển thị biểu đồ. Không dùng dữ liệu giả để trang trí.</div>`;return;}const maxX=Math.max(...points.map(p=>p.size))*1.2,colors={b0:'#728099',f16:'#9397e4',q8:'#454cc4'},w=640,h=260,left=51,right=22,top=23,bottom=44,pw=w-left-right,ph=h-top-bottom;let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Biểu đồ dung lượng MiB và mAP50–95, từ số đo nhóm nhập"><title>Dung lượng và mAP@50–95</title><desc>${points.map(p=>`${p.k}: ${num(p.size)} MiB, mAP ${num(p.ap)}`).join('; ')}</desc>`;[0,25,50,75,100].forEach(v=>{const y=top+ph-v/100*ph;svg+=`<line x1="${left}" y1="${y}" x2="${w-right}" y2="${y}" stroke="#e3e6ef"/><text x="${left-9}" y="${y+4}" text-anchor="end" fill="#7a8497" font-size="11">${v}</text>`;});for(let i=0;i<=4;i++){const x=left+pw*i/4;svg+=`<text x="${x}" y="${h-20}" text-anchor="middle" fill="#7a8497" font-size="10">${num(maxX*i/4,1)}</text>`;}svg+=`<text x="${left}" y="12" fill="#7a8497" font-size="10">mAP@50–95</text><text x="${w-right}" y="${h-3}" text-anchor="end" fill="#7a8497" font-size="10">Dung lượng (MiB)</text>`;points.forEach((p,i)=>{const x=left+p.size/maxX*pw,y=top+ph-p.ap/100*ph;svg+=`<circle cx="${x}" cy="${y}" r="6" fill="${colors[p.k]}" stroke="white" stroke-width="2"/><text x="${x+9}" y="${y-9+i%2*25}" fill="${colors[p.k]}" font-size="11" font-weight="600">${p.k.toUpperCase()}</text>`;});$('tradeoffPlot').innerHTML=svg+'</svg>';}
function syncPrintValues(){document.querySelectorAll('[data-print-for]').forEach(s=>{const input=$(s.dataset.printFor);if(!input)return;s.textContent=input.getAttribute('aria-invalid')==='true'?'Không hợp lệ':input.tagName==='SELECT'?input.options[input.selectedIndex]?.text:(input.value|| (input.type==='number'?'Chưa đo':'Chưa ghi'));});$('amendmentView').textContent=state.settings.projectNote||'Chưa có ghi chú thay đổi cấu hình.';$('protocolView').textContent=state.settings.protocolConfirmed?'Nhóm đã xác nhận khóa protocol.':'Chưa xác nhận khóa protocol.';}
function syncInputs(){document.querySelectorAll('input[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));document.querySelectorAll('[data-setting]').forEach(el=>{const v=state.settings[el.dataset.setting];if(el.type==='checkbox')el.checked=!!v;else el.value=v??'';});document.querySelectorAll('[data-metric]').forEach(el=>el.value=state.metrics[el.dataset.metric]??'');document.querySelectorAll('[data-model]').forEach(el=>el.value=state.metrics[el.dataset.model][el.dataset.field]??'');document.querySelectorAll('[data-evidence]').forEach(el=>el.value=state.evidence[el.dataset.evidence]??'');}
function renderBenchmarkEvidence(){const rows=JSON.parse($('benchmarkSummaryData').textContent);const source=rows.find(r=>r.model==='yolo26m-bdd100k.pt'),q8=rows.find(r=>r.model==='int8_yolo26m_640_openvino_model');if(source&&q8)$('checkpointStorageSummary').textContent=`Checkpoint nguồn lưu FP16: ${num(source.size)} MiB → INT8 ${num(q8.size)} MiB, giảm ${num((1-q8.size/source.size)*100)}%. Đây là mức giảm artifact gốc; mốc nguồn sạch chuẩn hóa vẫn cần xác minh.`;const row=rows.find(r=>r.model==='int8_yolo26s_qat_640_openvino_model');if(!row)return;$('qatBenchmarkSummary').textContent=`mAP@50–95 ${num(row.map95)}% trên 10.000 ảnh validation; latency ${num(row.lat,1)} ms trên 50 ảnh × 3 lượt, CPU 4 luồng, 640×640. ${row.benchmark_temporary?'Đang dùng snapshot benchmark tạm. ':''}${row.speedup==null?'Chưa có speedup cùng protocol.':`Tăng tốc ${num(row.speedup)}× so với YOLO26m CPU FP16${row.benchmark_temporary?' (snapshot tạm)':''}.`}`;}
function renderAll(){renderProgress();renderTimeline();renderTasks();renderTeam();renderDeliverables();renderEvaluation();renderBenchmarkEvidence();}
function openTask(id){const t=taskById(id),s=taskState(id);if(!t)return;editing={kind:'task',id};$('editEyebrow').textContent=`${id} · ${SCOPES[t.scope]} · ${t.priority}`;$('editTitle').textContent=t.title;const deps=incompleteDeps(t);$('editBody').innerHTML=`<div class="meta-row"><span class="pill accent">TV${t.owner} phụ trách</span><span class="pill">TV${t.reviewer} kiểm tra</span><span class="pill">${dayDate(t.start)} → ${dayDate(t.end)}</span></div><div class="detail-grid"><p><strong>Đầu vào</strong>${t.input}</p><p><strong>Đầu ra</strong>${t.output}</p><p><strong>Điều kiện hoàn thành</strong>${t.done}</p><p><strong>Phụ thuộc</strong>${t.deps.join(', ')||'Không — có thể khởi động song song.'}</p></div><details><summary>Rủi ro & phương án dự phòng</summary><div class="detail-body small"><p><strong>Rủi ro:</strong> ${t.risk}</p><p style="margin:0"><strong>Dự phòng:</strong> ${t.fallback}</p></div></details>${deps.length?`<div class="notice warn">Chưa thể đánh dấu hoàn thành: còn ${deps.join(', ')}. Có thể ghi chú hoặc cập nhật trạng thái đang làm.</div>`:''}<label class="field">Trạng thái<select id="editStatus">${Object.entries(STATUS).map(([v,label])=>`<option value="${v}" ${s.status===v?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Bằng chứng · bắt buộc khi hoàn thành<textarea id="editEvidence" maxlength="4000" placeholder="Tệp/log/commit, kết quả kiểm tra và người xác nhận">${esc(s.evidence)}</textarea></label><label class="field">Ghi chú<textarea id="editNote" maxlength="5000" placeholder="Vướng mắc, quyết định hoặc bước tiếp theo">${esc(s.note)}</textarea></label><div id="editError" class="dialog-error" role="alert"></div>`;$('editDialog').showModal();}
function openDelivery(id){const d=DATA.deliverables.find(d=>d.id===id),s=deliveryState(id);if(!d)return;editing={kind:'delivery',id};$('editEyebrow').textContent=`${id} · ${d.optional?'Tùy chọn':'Đầu ra bắt buộc'}`;$('editTitle').textContent=d.title;$('editBody').innerHTML=`<p class="muted small">${d.desc}</p><span class="pill">TV${d.owner} · Hạn ${dayDate(d.day)}</span><label class="field">Trạng thái<select id="editStatus"><option value="todo" ${!s.done?'selected':''}>Chưa hoàn thành</option><option value="done" ${s.done?'selected':''}>Hoàn thành có bằng chứng</option></select></label><label class="field">Bằng chứng bàn giao<textarea id="editEvidence" maxlength="4000" placeholder="Đường dẫn gói bàn giao/tệp/log/commit và người kiểm tra">${esc(s.evidence)}</textarea></label><label class="field">Ghi chú<textarea id="editNote" maxlength="5000">${esc(s.note)}</textarea></label><div id="editError" class="dialog-error" role="alert"></div>`;$('editDialog').showModal();}
function saveEdit(){if(!editing)return;const status=$('editStatus').value,evidence=$('editEvidence').value.trim(),note=$('editNote').value.trim();if(status==='done'&&!evidence){$('editError').textContent='Cần ghi bằng chứng trước khi đánh dấu hoàn thành.';return;}
 if(editing.kind==='task'){const t=taskById(editing.id);if(status==='done'&&incompleteDeps(t).length){$('editError').textContent='Còn phụ thuộc chưa hoàn thành: '+incompleteDeps(t).join(', ');return;}const completedDependents=DATA.tasks.filter(x=>x.deps.includes(t.id)&&taskState(x.id).status==='done');if(status!=='done'&&completedDependents.length){$('editError').textContent='Hãy mở lại các việc phụ thuộc đã hoàn thành trước: '+completedDependents.map(x=>x.id).join(', ');return;}state.tasks[t.id]={status,evidence,note};}else state.deliverables[editing.id]={done:status==='done',evidence,note};persist();$('editDialog').close();renderAll();toast('Đã lưu cập nhật theo xác nhận của nhóm.');}
function confirmAction(title,body,fn,label='Xác nhận'){confirmFn=fn;$('confirmTitle').textContent=title;$('confirmBody').textContent=body;$('confirmAction').textContent=label;$('confirmDialog').showModal();}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const csvCell=v=>'"'+(typeof v==='number'?String(v):String(v??'').replace(/^[=+@-]/,"'$&")).replace(/"/g,'""')+'"';
const csv=rows=>'\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n');
function exportProgress(){download('compression-lab-progress.json',JSON.stringify(state,null,2),'application/json');toast('Đã xuất JSON. Giữ file này để sao lưu hoặc chuyển cho nhóm.');}
function exportTasks(){const rows=[['Mã','Nhiệm vụ','Owner','Kiểm tra','Bắt đầu','Hạn','Ưu tiên','Phạm vi','Trạng thái','Phụ thuộc','Đầu vào','Đầu ra','Điều kiện hoàn thành','Rủi ro','Dự phòng','Bằng chứng','Ghi chú']];DATA.tasks.forEach(t=>{const s=taskState(t.id);rows.push([t.id,t.title,'TV'+t.owner,'TV'+t.reviewer,dayDate(t.start,true),dayDate(t.end,true),t.priority,SCOPES[t.scope],STATUS[s.status],t.deps.join('; '),t.input,t.output,t.done,t.risk,t.fallback,s.evidence,s.note]);});download('compression-lab-tasks.csv',csv(rows),'text/csv;charset=utf-8');}
function exportMetrics(){const m=state.metrics,rows=[['Kết quả do nhóm nhập; ô trống = Chưa đo'],['Chế độ tính toán','PyTorch FP16 / OpenVINO INT8; xem runtime đo thực'],['Source clean MiB',m.sourceSize??'Chưa đo'],['Dtype nguồn',state.settings.sourceDtype],['Run/config/final manifest',state.settings.runRef],['Baseline dev mAP50',m.dev50??'Chưa đo'],['Baseline dev mAP50-95',m.dev95??'Chưa đo'],['Model','MiB','mAP50','mAP50-95','p50 ms','p95 ms','Load ms']];Object.keys(MODEL_NAMES).forEach(k=>rows.push([MODEL_NAMES[k],...FIELDS.map(f=>m[k][f]??'Chưa đo')]));rows.push([],['Chỉ số Q8','Mốc','Q8','Thay đổi','Đơn vị','Ngưỡng','Kết quả']);criteria().forEach(r=>rows.push([r.name,r.base??'Chưa đo',r.after??'Chưa đo',r.change??'Chưa đo',r.changeUnit,r.threshold,r.change==null?'Chưa đo':r.pass(r.change)?'Đạt ngưỡng':'Chưa đạt']));rows.push([],['Kết luận hỗ trợ',$('resultBox').textContent],['Ghi chú/amendment',state.settings.projectNote]);Object.entries(EVIDENCE).forEach(([k,v])=>rows.push([v,state.evidence[k]||'Chưa ghi']));download('compression-lab-results.csv',csv(rows),'text/csv;charset=utf-8');}
async function importFile(file){if(!file)return;if(file.size>2*1024*1024){toast('File JSON quá lớn (giới hạn 2 MiB).',true);return;}try{const candidate=validateState(migratePrecisionState(migrateLegacyState(JSON.parse(await file.text()))));const count=Object.values(candidate.tasks).filter(t=>t.status==='done').length;confirmAction('Nhập tiến độ từ JSON',`File ${file.name} có ${count} nhiệm vụ hoàn thành. Thao tác sẽ thay trạng thái và số đo đang có trong dashboard này. Nên xuất JSON hiện tại trước nếu cần giữ bản sao.`,()=>{state=candidate;persist();syncInputs();renderAll();toast('Đã nhập tiến độ và số liệu từ JSON.');},'Thay bằng dữ liệu này');}catch(e){toast('Không nhập được: '+e.message,true);}finally{$('importFile').value='';}}
function invalidateMetric(el,message){el.setAttribute('aria-invalid','true');if(el.dataset.model)state.metrics[el.dataset.model][el.dataset.field]=null;else state.metrics[el.dataset.metric]=null;persist();renderEvaluation();toast(message,true);}
function handleNumeric(el){if(el.value===''&&el.validity.badInput){invalidateMetric(el,'Giá trị số chưa hợp lệ.');return;}let v=el.value===''?null:Number(el.value);const isAP=el.dataset.field?.startsWith('map')||['dev50','dev95'].includes(el.dataset.metric),isDrop=el.dataset.metric==='maxClassDrop';if(v!=null&&(!Number.isFinite(v)||(isAP&&(v<0||v>100))||(isDrop&&(v< -100||v>100))||(!isAP&&!isDrop&&v<=0))){invalidateMetric(el,isAP?'mAP phải trong khoảng 0–100.':isDrop?'Delta AP phải trong khoảng −100 đến 100.':'Dung lượng và thời gian phải lớn hơn 0.');return;}el.removeAttribute('aria-invalid');if(el.dataset.model)state.metrics[el.dataset.model][el.dataset.field]=v;else state.metrics[el.dataset.metric]=v;persist();renderEvaluation();}
function setMenu(open){$('sidebar').classList.toggle('open',open);$('overlay').classList.toggle('visible',open);$('menuBtn').setAttribute('aria-expanded',String(open));}
document.addEventListener('click',e=>{const t=e.target.closest('[data-task]');if(t){openTask(t.dataset.task);return;}const d=e.target.closest('[data-delivery]');if(d){openDelivery(d.dataset.delivery);return;}const day=e.target.closest('[data-day]');if(day){selectedDay=+day.dataset.day;renderTimeline();return;}const close=e.target.closest('[data-close]');if(close)$(close.dataset.close).close();});
$('saveEdit').addEventListener('click',saveEdit);$('confirmAction').addEventListener('click',()=>{const f=confirmFn;confirmFn=null;$('confirmDialog').close();if(f)f();});
$('menuBtn').addEventListener('click',()=>setMenu(!$('sidebar').classList.contains('open')));$('overlay').addEventListener('click',()=>setMenu(false));document.addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false);});
document.querySelectorAll('.nav a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));
$('settingsBtn').addEventListener('click',()=>$('settingsDialog').showModal());$('editAmendment').addEventListener('click',()=>$('settingsDialog').showModal());$('exportBtn').addEventListener('click',exportProgress);$('importBtn').addEventListener('click',()=>$('importFile').click());$('importFile').addEventListener('change',e=>importFile(e.target.files[0]));$('exportTasksBtn').addEventListener('click',exportTasks);$('exportMetricsBtn').addEventListener('click',exportMetrics);
$('resetBtn').addEventListener('click',()=>confirmAction('Đặt lại dashboard?','Tất cả trạng thái, bằng chứng và số đo sẽ trở về kế hoạch chưa bắt đầu. Các tệp model/dữ liệu của nhóm không bị ảnh hưởng. Hãy xuất JSON trước nếu cần giữ bản sao.',()=>{state=emptyState();persist();syncInputs();renderAll();$('settingsDialog').close();toast('Đã đặt lại. Không có nhiệm vụ hay kết quả thực nghiệm hoàn thành.');},'Đặt lại'));
['taskSearch','ownerFilter','statusFilter','priorityFilter','scopeFilter','readyOnly'].forEach(id=>$(id).addEventListener(id==='taskSearch'?'input':'change',()=>renderTasks()));$('clearFilters').addEventListener('click',()=>{['taskSearch','ownerFilter','statusFilter','priorityFilter','scopeFilter'].forEach(id=>$(id).value='');$('readyOnly').checked=false;renderTasks();});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.setting){state.settings[el.dataset.setting]=el.type==='checkbox'?el.checked:el.value;persist();if(el.dataset.setting==='startDate'){renderTimeline();renderTasks();renderDeliverables();}renderEvaluation();}else if(el.dataset.model||el.dataset.metric)handleNumeric(el);else if(el.dataset.evidence){state.evidence[el.dataset.evidence]=el.value.slice(0,4000);persist();renderEvaluation();}});
document.addEventListener('input',e=>{if(e.target.dataset.model||e.target.dataset.metric)handleNumeric(e.target);else if(e.target.dataset.evidence||e.target.id==='projectNote'||e.target.id==='runRef')e.target.dispatchEvent(new Event('change',{bubbles:true}));});
function beforePrint(){printDetails=[...document.querySelectorAll('details')].map(el=>[el,el.open]);printDetails.forEach(([el])=>el.open=true);renderTasks(true);syncPrintValues();}
function afterPrint(){printDetails.forEach(([el,open])=>el.open=open);printDetails=[];renderTasks();}
window.addEventListener('beforeprint',beforePrint);window.addEventListener('afterprint',afterPrint);$('printBtn').addEventListener('click',()=>window.print());
if(state.tasks.T04?.evidence.includes('requirements.txt và .venv'))state.tasks.T04.evidence='requirements.txt ghim dependency runtime; report ghi phiên bản và số luồng thực tế.';
if(state.tasks.T17?.evidence.includes('conf 0.25'))state.tasks.T17.evidence='Evaluation: 640x640, conf=0.001, iou=0.7, maxDets=300; UI demo khởi đầu conf=0.25.';
if(state.tasks.O01?.evidence.includes('11 model')||state.tasks.O01?.evidence.includes('9 cấu hình'))state.tasks.O01.evidence='Đo p50, p95, mean latency và FPS cho 6 cấu hình 640x640 còn artifact tái lập.';
renderStatic();syncInputs();renderAll();
if(state.updatedAt)$('footerState').textContent='Dữ liệu khôi phục · '+new Date(state.updatedAt).toLocaleString('vi-VN');
const sections=[...document.querySelectorAll('main section.section')];let scrollTick=false;function updateNav(){const target=sections.reduce((last,s)=>s.getBoundingClientRect().top<=145?s:last,sections[0]);document.querySelectorAll('.nav a').forEach(a=>{const active=a.getAttribute('href')==='#'+target.id;a.classList.toggle('active',active);if(active){a.setAttribute('aria-current','location');$('currentSection').textContent=a.textContent.replace(/^\d+\s*/, '').trim();}else a.removeAttribute('aria-current');});scrollTick=false;}
window.addEventListener('scroll',()=>{if(!scrollTick){requestAnimationFrame(updateNav);scrollTick=true;}},{passive:true});updateNav();
