window.compressionDashboard={version:1,taskCount:DATA.tasks.length,getState:()=>JSON.parse(JSON.stringify(state)),criteria:()=>criteria().map(({pass,...r})=>({...r,status:r.change==null?'unmeasured':pass(r.change)?'pass':'fail'}))};
